steps.script:
try {
$d='C:\TTiTTulares\image-approval-receipts'
$a=@(Get-ChildItem -LiteralPath $d -File -Filter '*.json' | Where-Object {$_.Name -match '^(tt|tr)-img-'} | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 14)
$o=@()
foreach($f in $a){
 try {
 $j=Get-Content -LiteralPath $f.FullName -Raw | ConvertFrom-Json
 $o+=@{file=$f.Name;utc=$f.LastWriteTimeUtc.ToString('o');state=$j.state;receivedAt=$j.receivedAt;project=$j.project;revision=$j.revision;hasReceiptId=([string]$j.id).Length -gt 0;hasRasterHash=([string]$j.rasterSHA256).Length -eq 64}
 }catch{$o+=@{file=$f.Name;error='invalid_json'}}
}
Write-Output ('TTRESULT:'+(@{rows=$o}|ConvertTo-Json -Compress -Depth 5))
}catch{Write-Output ('TTRESULT:'+(@{error=$_.Exception.Message}|ConvertTo-Json -Compress))}
